var minimumDeletions = function(nums) {
    const n = nums.length;
    let minPos = 0;
    let maxPos = 0;

    for (let i = 1; i < n; i++) {
        if (nums[i] < nums[minPos]) minPos = i;
        if (nums[i] > nums[maxPos]) maxPos = i;
    }

    const sameSideStart = Math.max(minPos, maxPos) + 1;
    const sameSideEnd = n - Math.min(minPos, maxPos);
    const oppositeStart = minPos + 1 + n - maxPos;
    const oppositeEnd = maxPos + 1 + n - minPos;

    return Math.min(sameSideStart, sameSideEnd, oppositeStart, oppositeEnd);
};

/**
