var minimumDeletions = function(nums) {
    const n = nums.length;
    let minPos = 0;
    let maxPos = 0;

    for (let i = 1; i < n; i++) {
        if (nums[i] < nums[minPos]) minPos = i;
        if (nums[i] > nums[maxPos]) maxPos = i;
    }

    const earliest = Math.min(minPos, maxPos);
    const latest = Math.max(minPos, maxPos);

    const sameSideStart = latest + 1;
    const sameSideEnd = n - earliest;
    const oppositeSides = earliest + 1 + n - latest;

    return Math.min(sameSideStart, sameSideEnd, oppositeSides);
};
